const item = $input.first().json;
const body = item.body && typeof item.body === 'object' ? item.body : item;
const agent_id = String(body.agent_id || '').trim();
const action = String(body.action || '').trim();
if (!agent_id || !action) {
  throw new Error('agent_id y action requeridos');
}
const base = String($env.CASTUO_BASE_URL || $env.CASTUO_API_URL || 'http://localhost:8000').replace(/\/$/, '');
let backend_put = { skipped: true };
if (base) {
  try {
    const r = await fetch(base + '/workspace/agents', { method: 'GET' });
    backend_put = { http_status: r.status, note: 'Listado workspace; PUT por agente no implementado en stub' };
  } catch (e) {
    backend_put = { error: e.message };
  }
}
let gaia = { skipped: true };
const gurl = String($env.N8N_GAIACHAIN_API || '').trim();
const gkey = String($env.N8N_GAIACHAIN_API_KEY || '').trim();
if (gurl && gkey) {
  try {
    const r = await fetch(gurl.replace(/\/$/, ''), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: 'Bearer ' + gkey,
      },
      body: JSON.stringify({
        agent_id,
        action,
        timestamp: new Date().toISOString(),
        data: body,
      }),
    });
    gaia = { http_status: r.status, text: await r.text() };
  } catch (e) {
    gaia = { error: e.message };
  }
}
return [
  {
    json: {
      agent_id,
      action,
      status: 'accepted',
      slack_text: 'Agente ' + agent_id + ' acción ' + action,
      slack_channel: String($env.N8N_SLACK_ALERTS || '').trim(),
      powerbi_url: String($env.N8N_POWERBI_ENDPOINT || '').trim(),
      gaia,
      backend_probe: backend_put,
    },
  },
];
